nextflow_process {

    name "Test Process DECOUPLER_DECOUPLER"
    script "../main.nf"
    process "DECOUPLER_DECOUPLER"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "decoupler"
    tag "decoupler/decoupler"

    test("differential abundance data - normalized counts - mouse") {

        when {
            params {
                module_args = "--min_n 2 --transpose TRUE --ensembl_ids TRUE --methods mlm --features_id_col gene_id --features_symbol_col gene_name"
            }
            process {
                """
                input[0] = [
                    ['id':'treatment_mCherry_hND6', 'method_differential':'deseq2'],
                    file("https://github.com/nf-core/test-datasets/raw/differentialabundance/modules_testdata/treatment_mCherry_hND6_.deseq2.results.tsv", checkIfExists: true)
                ]
                input[1] = [
                    ['id':'network'],
                    file("https://github.com/nf-core/test-datasets/raw/differentialabundance/modules_testdata/progeny/mouse_network.tsv", checkIfExists: true)
                ]
                input[2] = [
                    ['id':'annot'],
                    file("https://github.com/nf-core/test-datasets/raw/differentialabundance/modules_testdata/Mus_musculus.anno.feature_metadata.tsv", checkIfExists: true)]
                """
            }
        }

    then {
        def estimateFiles = process.out.dc_estimate[0][1].collect { path(it) }
        def pvalsFiles = process.out.dc_pvals[0][1].collect { path(it) }
        def pngFiles = process.out.png[0][1].collect { path(it) }

        assertAll(
            { assert process.success },
            { estimateFiles.each { f -> assert f.exists() } },
            { pvalsFiles.each { f -> assert f.exists() } },
            { pngFiles.each { f -> assert f.exists() } },
            { estimateFiles.each { f -> assert f.getText().contains("\tAndrogen\tEGFR\tEstrogen\tHypoxia\tJAK-STAT\tMAPK\tNFkB\tPI3K\tTGFb\tTNFa\tTrail\tVEGF\tWNT\tp53")} },
            { assert estimateFiles.find { it.getFileName().toString().contains("mlm_estimate") }?.getText()?.contains("treatment_mCherry_hND6\t-0.0")},
            { assert estimateFiles.find { it.getFileName().toString().contains("consensus_estimate") }?.getText()?.contains("treatment_mCherry_hND6\t-0.0")},
            { pvalsFiles.each { f -> assert f.getText().contains("\tAndrogen\tEGFR\tEstrogen\tHypoxia\tJAK-STAT\tMAPK\tNFkB\tPI3K\tTGFb\tTNFa\tTrail\tVEGF\tWNT\tp53")} },
            { assert pvalsFiles.find { it.getFileName().toString().contains("mlm_pvals") }?.getText()?.contains("treatment_mCherry_hND6\t0.9")},
            { assert pvalsFiles.find { it.getFileName().toString().contains("consensus_pvals") }?.getText()?.contains("treatment_mCherry_hND6\t0.9")},
            { assert snapshot(
                    estimateFiles*.getFileName().toString(),
                    pvalsFiles*.getFileName().toString(),
                    pngFiles*.getFileName().toString(),
                    estimateFiles*.readLines().size(),
                    pvalsFiles*.readLines().size(),
                    process.out
                        .findAll { key, val -> key.startsWith('versions') }
                        .collect { key, val -> [ (key) : path(val[0]).yaml ] }
            ).match()}
        )
    }
    }

    test("decoupler_test") {

        when {
            params {
                module_args = "--min_n 1 --features_id_col gene_id --features_symbol_col gene_name"
            }

            process {
                """
                input[0] = [
                    [ id: 'test', 'method_differential':'deseq2'],
                    file(params.modules_testdata_base_path + 'generic/tsv/expression.tsv', checkIfExists: true)
                ]
                input[1] = [
                    ['id':'network'],
                    file(params.modules_testdata_base_path + 'generic/tsv/network.tsv', checkIfExists: true)
                ]
                input[2] = [
                    ['id':'annot'],
                    file("https://github.com/nf-core/test-datasets/raw/differentialabundance/modules_testdata/Mus_musculus.anno.feature_metadata.tsv", checkIfExists: true)]
                """
            }
        }

        then {
            def estimateFiles = process.out.dc_estimate[0][1].collect { path(it) }
            def pvalsFiles = process.out.dc_pvals[0][1].collect { path(it) }
            def pngFiles = process.out.png[0][1].collect { path(it) }

            assertAll(
                { assert process.success },
                { estimateFiles.each { f -> assert f.exists() } },
                { pvalsFiles.each { f -> assert f.exists() } },
                { pngFiles.each { f -> assert f.exists() } },
                { estimateFiles.collect { f -> assert f.getText().contains("\tT1\tT2\tT3\tT4\tT5")} },
                { assert estimateFiles.find { it.getFileName().toString().contains("ulm_estimate") }?.getText()?.contains("S01\t4.0") },
                { assert estimateFiles.find { it.getFileName().toString().contains("consensus_estimate") }?.getText()?.contains("S01\t1.1") },
                { pvalsFiles.collect { f -> assert f.getText().contains("\tT1\tT2\tT3\tT4\tT5")} },
                { assert pvalsFiles.find { it.getFileName().toString().contains("ulm_pvals") }?.getText()?.contains("S01\t0.0") },
                { assert pvalsFiles.find { it.getFileName().toString().contains("consensus_pvals") }?.getText()?.contains("S01\t0.2") },
                { assert snapshot(
                    estimateFiles*.getFileName().toString(),
                    pvalsFiles*.getFileName().toString(),
                    pngFiles*.getFileName().toString(),
                    estimateFiles*.readLines().size(),
                    pvalsFiles*.readLines().size(),
                    process.out
                        .findAll { key, val -> key.startsWith('versions') }
                        .collect { key, val -> [ (key) : path(val[0]).yaml ] }
                ).match()}
            )
        }
    }

    test("decoupler stub") {
        options "-stub"

        when {
            params {
                module_args = "--min_n 1 --features_id_col gene_id --features_symbol_col gene_name"
            }
            process {
                """
                input[0] = [
                    [ id: 'test' ],
                    file(params.modules_testdata_base_path + 'generic/tsv/expression.tsv', checkIfExists: true)
                ]
                input[1] = [
                    ['id':'network'],
                    file(params.modules_testdata_base_path + 'generic/tsv/network.tsv', checkIfExists: true)
                ]
                input[2] = [
                    ['id':'annot'],
                    file("https://github.com/nf-core/test-datasets/raw/differentialabundance/modules_testdata/Mus_musculus.anno.feature_metadata.tsv", checkIfExists: true)]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(process.out),
                    process.out
                        .findAll { key, val -> key.startsWith('versions') }
                        .collect { key, val -> [ (key) : path(val[0]).yaml ] }
                ).match() }
            )
        }
    }

}

